eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   tr: () => (/* binding */ tr)\n/* harmony export */ });\n// All Turkish copy. Keys mirror the original site's dictionary.\nconst tr = {\n    \"nav.stay\": \"ODALAR\",\n    \"nav.dine\": \"GASTRONOMİ\",\n    \"nav.experiences\": \"DENEYİMLER\",\n    \"nav.weddings\": \"DÜĞÜNLER\",\n    \"nav.weddingsWinter\": \"KONSERLER\",\n    \"nav.bookNow\": \"REZERVASYON\",\n    \"nav.openMenu\": \"Menüyü aç\",\n    \"nav.closeMenu\": \"Menüyü kapat\",\n    \"nav.menuTitle\": \"Menü\",\n    \"nav.seasonToggle\": \"Sezonu değiştir\",\n    \"hero.summer\": \"Yaz\",\n    \"hero.winter\": \"Kış\",\n    \"hero.summerSeason\": \"Yaz Sezonu\",\n    \"hero.winterSeason\": \"Kış Sezonu\",\n    \"hero.summerShort\": \"Yaz\",\n    \"hero.winterShort\": \"Kış\",\n    \"hero.seasonLabel\": \"Sezon seçimi\",\n    \"hero.summerTooltip\": \"Nisan – Ekim\",\n    \"hero.winterTooltip\": \"Kasım – Mart\",\n    \"hero.discover\": \"Keşfet\",\n    \"about.title1\": \"Özenle işlenmiş,\",\n    \"about.title2\": \"titizlikle tasarlanmış.\",\n    \"about.bodySummer\": \"Villa Aurelia; mimariye, ışığa ve orada yaşanan hayata duyulan derin bir saygıyla tasarlandı. Her oda; doğal dokular, dingin tonlar ve özenle seçilmiş parçalarla katman katman kuruluyor. Dengeye ve ayrıntıya olan bağlılığımız, villanın her köşesini hem rafine hem de tamamen konforlu kılıyor; Antalya kıyısında sessiz bir sığınak.\",\n    \"about.bodyWinter\": \"Villa Aurelia; mimariye, ışığa ve orada yaşanan hayata duyulan derin bir saygıyla tasarlandı. Her oda; doğal dokular, dingin tonlar ve özenle seçilmiş parçalarla katman katman kuruluyor. Dengeye ve ayrıntıya olan bağlılığımız, villanın her köşesini hem rafine hem de tamamen konforlu kılıyor; kar hattının hemen üstünde sessiz bir sığınak.\",\n    \"rooms.eyebrow\": \"ODALAR & SÜİTLER\",\n    \"rooms.included\": \"DAHİL\",\n    \"rooms.sleeping\": \"Yatak sayısı\",\n    \"rooms.bathroom\": \"Banyo\",\n    \"rooms.bookARoom\": \"Oda Rezerve Et\",\n    \"rooms.prev\": \"ÖNCEKİ\",\n    \"rooms.next\": \"SONRAKİ\",\n    \"rooms.selectRoom\": \"Oda seçin\",\n    \"room.suite.label\": \"Süit\",\n    \"room.suite.title\": \"Dinlenmek ve\",\n    \"room.suite.subtitle\": \"huzur bulmak için ideal yer\",\n    \"room.deluxe.label\": \"Deluxe\",\n    \"room.deluxe.title\": \"Denizle çerçevelenmiş\",\n    \"room.deluxe.subtitle\": \"açık bir ufuk\",\n    \"room.garden.label\": \"Bahçeli Villa\",\n    \"room.garden.title\": \"Selvi gölgesinde\",\n    \"room.garden.subtitle\": \"geçen yavaş günler\",\n    \"room.imperial.label\": \"İmperial Süit\",\n    \"room.imperial.title\": \"Ayrıcalıklı konaklamalar için\",\n    \"room.imperial.subtitle\": \"görkemli bir sığınak\",\n    \"amenity.seaView\": \"Deniz manzarası\",\n    \"amenity.airCon\": \"Klima\",\n    \"amenity.kingBed\": \"King yatak\",\n    \"amenity.walkInCloset\": \"Giyinme odası\",\n    \"amenity.wifi\": \"Wi-Fi\",\n    \"amenity.espresso\": \"Espresso barı\",\n    \"amenity.privateTerrace\": \"Özel teras\",\n    \"amenity.rainShower\": \"Yağmurlama duş\",\n    \"amenity.miniBar\": \"Mini bar\",\n    \"amenity.bathrobes\": \"Bornoz\",\n    \"amenity.plungePool\": \"Özel havuz\",\n    \"amenity.gardenPatio\": \"Bahçe terası\",\n    \"amenity.outdoorDaybed\": \"Açık hava daybed\",\n    \"amenity.livingArea\": \"Oturma alanı\",\n    \"amenity.butlerService\": \"Butler servisi\",\n    \"amenity.marbleFireplace\": \"Mermer şömine\",\n    \"amenity.panoramicSeaView\": \"Panoramik deniz manzarası\",\n    \"amenity.privateLounge\": \"Özel lounge\",\n    \"amenity.chandelier\": \"Avize\",\n    \"amenity.privateChef\": \"Özel şef\",\n    \"exp.eyebrow\": \"DENEYİMLER\",\n    \"exp.titleSummer\": \"Küçük ritüellerden\",\n    \"exp.titleWinter\": \"Küçük ritüellerden\",\n    \"exp.titleSub\": \"oluşan bir mevsim.\",\n    \"exp.introSummer\": \"Sahilde gün doğumundan denizin kıyısındaki müzikli akşamlara kadar — Villa Aurelia'da her gün, yavaşça yaşanmak ve içtenlikle hatırlanmak üzere kurgulanmış anlardan oluşuyor.\",\n    \"exp.introWinter\": \"İlk ışıkta taze karlardan alpin gökyüzü altındaki şömine başı akşamlarına kadar — Villa Aurelia'da her gün, yavaşça yaşanmak ve içtenlikle hatırlanmak üzere kurgulanmış anlardan oluşuyor.\",\n    \"exp.pool.title\": \"Yüzme Havuzu\",\n    \"exp.pool.desc\": \"Akdeniz'in ufkuyla buluşan sonsuzluk havuzu. Şezlonglar, özenli servis ve yaz öğleden sonralarının yavaş ritmi bir arada.\",\n    \"exp.beach.title\": \"Özel Plaj\",\n    \"exp.beach.desc\": \"Yalnızca misafirlerimize ayrılmış, ince kumlu ve turkuaz sulu sakin bir sahil. Kabanalar, plaj butlerları ve sessiz kaçamaklar sizi bekliyor.\",\n    \"exp.golf.title\": \"Golf Sahası\",\n    \"exp.golf.desc\": \"Selvilerle çevrili yeşil sahalar arasında on sekiz delik. Şafakta, çimenlerden yükselen sisin ve uzaktaki dağların eşliğinde oyununuza başlayın.\",\n    \"exp.concert.title\": \"Canlı Konserler\",\n    \"exp.concert.desc\": \"Yıldızlı gökyüzü altında yaylı sazlar, caz ve dingin akustik setlerle geçen açık hava akşamları. Gecenin bir parçası olan müzik.\",\n    \"exp.bar.title\": \"Kokteyl Bar\",\n    \"exp.bar.desc\": \"Amber ışıklar, mermer tezgâhlar ve her gece hazırlanan imza kokteyller. Oyalanmak, müziği dinlemek ve akşamın ağır ağır açılışını izlemek için ideal.\",\n    \"exp.tea.title\": \"İkindi Çayı\",\n    \"exp.tea.desc\": \"Katlı porselenler, bahçe manzarası ve özenle seçilmiş çay çeşitleri. Terasta ev yapımı hamur işleriyle sunulan günlük bir ritüel.\",\n    \"exp.spa.title\": \"Hamam & Spa\",\n    \"exp.spa.desc\": \"Mum ışığında taş odalar, ılık mermer ve yüzyılların Akdeniz geleneğinden süzülen ritüeller. Beden ve zihin için sessiz bir yenilenme.\",\n    \"exp.yacht.title\": \"Gün Batımı Yelken\",\n    \"exp.yacht.desc\": \"Altın saatlerde Antalya kıyısı boyunca özel yat turları. Şampanya, sakin denizler ve akşama doğru yavaş bir sürüklenme.\",\n    \"exp.yoga.title\": \"Gün Doğumu Yogası\",\n    \"exp.yoga.desc\": \"Keten perdeler, denizin üzerinde ahşap bir güverte ve dalgaların ritmine göre şekillenen bir sabah pratiği.\",\n    \"exp.dining.title\": \"Teras Yemeği\",\n    \"exp.dining.desc\": \"Zeytin ağaçlarının altında mum ışığında masalar, yerel ürünlerden hazırlanan tadım menüsü ve Akdeniz akşamının sıcak sessizliği.\",\n    \"exp.thermal.title\": \"Termal Havuz\",\n    \"exp.thermal.desc\": \"Karla kaplı zirvelere karşı buğulanan ısıtmalı sonsuzluk havuzu. Akşamüstü suya bırakın kendinizi; sisin alpin gökyüzüne yükselişini izleyin.\",\n    \"exp.terrace.title\": \"Kar Terası\",\n    \"exp.terrace.desc\": \"Kaşmir battaniyeler, harıl harıl yanan şömineler ve vadiye açılan özel bir teras. Ağaç hattının üzerinde sessiz sabahlar.\",\n    \"exp.ski.title\": \"Kayak Pistleri\",\n    \"exp.ski.desc\": \"İlk ışıkta bakir kar, doğrudan pistten çıkış imkânı ve dağın her gizli hattını bilen deneyimli eğitmenler.\",\n    \"exp.concertWinter.desc\": \"Büyük şöminenin yanında canlı yaylı sazlar ve akustik setler. Ateşin çıtırtısına eşlik eden müzik.\",\n    \"exp.concertWinter.title\": \"Şömine Başı Konser\",\n    \"exp.barWinter.title\": \"Viski Lounge\",\n    \"exp.barWinter.desc\": \"Nadir single malt viskiler, derin deri koltuklar ve gaz lambalarının amber parıltısı. Ağır ilerleyen akşamlar için tasarlanmış bir oda.\",\n    \"exp.teaWinter.desc\": \"Katlı porselenler, ev yapımı hamur işleri ve buğulu pencerelerin yanında sunulan sıcak demlikler. Kışa özel günlük bir ritüel.\",\n    \"exp.spaWinter.desc\": \"Mum ışığında taş odalar, ılık mermer ve her katmandaki soğuğu çözen ritüeller. Kış yolcuları için sessiz bir yenilenme.\",\n    \"exp.sleigh.title\": \"Kızak Turu\",\n    \"exp.sleigh.desc\": \"Akşamüstü karlı çam ormanlarında süzülen özel atlı kızaklar. Kürk örtüler, fenerler ve düşen karın sessizliği.\",\n    \"exp.yogaWinter.desc\": \"Kar hattının üzerinde camlı bir stüdyo, keten perdeler ve ahşap bir güverte; kışın sessizliğine göre şekillenen sabah pratiği.\",\n    \"exp.diningWinter.title\": \"Alpin Yemek\",\n    \"exp.diningWinter.desc\": \"Dağ manzarasıyla çerçevelenmiş mum ışığında masalar, yerel ürünlerden hazırlanan doyurucu tadım menüsü ve şale akşamının sıcak sessizliği.\",\n    \"dine.discover\": \"KEŞFET\",\n    \"dine.hall.title\": \"Büyük Salon\",\n    \"dine.terrace.title\": \"Teras\",\n    \"dine.bar.title\": \"Aurelia Bar\",\n    \"dine.summer.hall.eyebrow\": \"ÖĞLE YEMEĞİ, İKİNDİ ÇAYI VE AKŞAM YEMEĞİ\",\n    \"dine.summer.hall.body\": \"Geniş manzarası, uluslararası mutfağı, kokteylleri ve hafif tabaklarıyla efsanevi Büyük Salon, Antalya'nın “oturma odası” olarak bilinir. Villa Aurelia'nın terasında canlı piyano eşliğinde sunulan ikindi çayında gerçek zarafeti deneyimleyin.\",\n    \"dine.summer.terrace.eyebrow\": \"AÇIK HAVADA YEMEK\",\n    \"dine.summer.terrace.body\": \"Gündüz güneşle yıkanan, gece mum ışığıyla aydınlanan Teras, zeytin ağaçları ve begonvillerin altında hayat bulur. Deniz esintisi sütunların arasından süzülürken Akdeniz mezeleri, odun ateşinde pişen spesiyaller ve dinç yerel şaraplar sunulur.\",\n    \"dine.summer.bar.eyebrow\": \"KOKTEYLLER VE GEÇ SAATLER\",\n    \"dine.summer.bar.body\": \"Kadife, pirinç ve amber ışığın buluştuğu mahrem bir sığınak. Aurelia Bar; özel kokteyller, nadir yıllanmış şaraplar ve gecenin geç saatlerine dek uzanan dingin caz melodileriyle aperitivo'nun altın çağını yaşatır.\",\n    \"dine.winter.hall.eyebrow\": \"İKİNDİ ÇAYI VE ŞÖMİNE BAŞI YEMEK\",\n    \"dine.winter.hall.body\": \"Kışın villanın oturma odası — tonozlu tavanlar, harıl harıl yanan şömineler ve buzla süslenmiş pencereler bir arada. İkindi çayı ateşin yanında sunulur; dışarıdaki çamlara kar yağarken akşamları uluslararası mutfak servis edilir.\",\n    \"dine.winter.terrace.eyebrow\": \"DUMAN VE ATEŞTE YEMEK\",\n    \"dine.winter.terrace.body\": \"Vadinin üzerinde ısıtmalı cam kubbenin altında Teras, kışın dumana ve ateşe teslim olur. Odun dumanı kloşları altında pişen tabaklar, alpin av etleri ve sıcak baharatlı şaraplar, fenerler kar yağışına karşı parlarken sofraya gelir.\",\n    \"dine.winter.bar.eyebrow\": \"VİSKİ VE GEÇ SAATLER\",\n    \"dine.winter.bar.body\": \"Lacivert kadife, mat gümüş ve alçak amber ışığın buluştuğu mahrem bir sığınak. Aurelia Bar; tütsülü kokteyller, nadir single malt viskiler ve uzun kış geceleri boyunca yumuşakça uzanan dingin cazla ağırlar sizi.\",\n    \"wed.summer.eyebrow\": \"DÜĞÜNLER & KUTLAMALAR\",\n    \"wed.summer.titleTop\": \"Zamansız bir zarafetle\",\n    \"wed.summer.titleBottom\": \"“Evet” deyin.\",\n    \"wed.summer.body\": \"Villa Aurelia; olağanüstü bir başlangıç arayan çiftlere bahçelerini, teraslarını ve balo salonlarını açar. Selvi ağaçları altındaki mahrem törenlerden mum ışığındaki avizelerin altında düzenlenen büyük resepsiyonlara kadar her ayrıntı, misafirlerimize gösterdiğimiz özenle kurgulanır. Adanmış organizatörler, özenle hazırlanmış menüler ve özel bir malikâne hissi veren bir mekân — bir günlüğüne size ait, sonsuza dek hatırlanacak.\",\n    \"wed.summer.g1\": \"Kapasite: 80 – 120 misafir\",\n    \"wed.summer.g2\": \"Mekânlar: Bahçe, Teras & Balo Salonu\",\n    \"wed.summer.g3\": \"Mevsimler: İlkbahar–Sonbahar\",\n    \"wed.winter.eyebrow\": \"CANDLELIGHT KONSERLERİ\",\n    \"wed.winter.titleTop\": \"Bin mum,\",\n    \"wed.winter.titleBottom\": \"tek bir kış akşamı.\",\n    \"wed.winter.body\": \"Kışın Büyük Salon bin mumla aydınlanır ve tamamen müziğe bırakılır. Yerleşik yaylı dörtlümüz, solo piyanistimiz ve konuk topluluklar; kemerli pencerelere kar yağarken Vivaldi, Chopin ve film müzikleri çalar. Koltuk sayısı sınırlıdır, battaniyeler hazırdır ve arada sıcak şarabınız sizi bekler.\",\n    \"wed.winter.g1\": \"Kapasite: 60 – 90 koltuk\",\n    \"wed.winter.g2\": \"Mekânlar: Büyük Salon, Kış Salonu & Mahzen\",\n    \"wed.winter.g3\": \"Akşamlar: Perşembe–Pazar, 19.30\",\n    \"wed.glance\": \"Bir bakışta\",\n    \"book.eyebrow\": \"REZERVASYONLAR\",\n    \"book.title1\": \"Konaklamanızı\",\n    \"book.title2\": \"Villa Aurelia'da ayırtın.\",\n    \"book.intro\": \"Gelişinizi biz hazırlayalım. Tarihlerinizi ve tercihlerinizi paylaşın; misafir ilişkileri ekibimiz 24 saat içinde rezervasyonunuzu onaylasın.\",\n    \"book.dates\": \"Tarihler\",\n    \"book.datesPh\": \"Giriş ve çıkış tarihi seçin\",\n    \"book.nights\": \"gece\",\n    \"book.legendOpen\": \"Müsait\",\n    \"book.legendLimited\": \"Sınırlı\",\n    \"book.legendFull\": \"Dolu\",\n    \"book.availOpen\": \"Tüm geceler müsait —\",\n    \"book.availLimited\": \"Sınırlı müsaitlik —\",\n    \"book.availFull\": \"Seçtiğiniz aralıkta dolu geceler var. Lütfen farklı tarihler seçin.\",\n    \"book.roomsLeft\": \"oda kaldı\",\n    \"book.roomsShort\": \"oda\",\n    \"book.adults\": \"Yetişkin\",\n    \"book.children\": \"Çocuk\",\n    \"book.roomPref\": \"Oda Tercihi\",\n    \"book.selectRoom\": \"Oda tipi seçin\",\n    \"book.name\": \"Ad Soyad\",\n    \"book.namePh\": \"Adınız\",\n    \"book.email\": \"E-posta Adresi\",\n    \"book.phone\": \"Telefon\",\n    \"book.requests\": \"Özel İstekler\",\n    \"book.requestsPh\": \"Özel bir gün, diyet gereksinimi veya oda tercihi belirtebilirsiniz…\",\n    \"book.submit\": \"Rezervasyon Talep Et\",\n    \"ready.title\": \"Hazır mısınız?\",\n    \"ready.title2\": \"Aurelia'yı deneyimlemeye.\",\n    \"ready.bodySummer\": \"Konaklamanızı bugün ayırtın; Antalya kıyısında deniz kenarı lüksünü, nefes kesici manzaraları ve unutulmaz anları keşfedin.\",\n    \"ready.bodyWinter\": \"Konaklamanızı bugün ayırtın; alpin lüksünü, kar beyazı sabahları ve şöminenin yanında unutulmaz akşamları keşfedin.\",\n    \"foot.stayInTouch\": \"İletişimde kalın\",\n    \"foot.lettersTop\": \"Akdeniz'den\",\n    \"foot.lettersBottom\": \"mektuplar.\",\n    \"foot.newsletterBody\": \"Sezon açılışları, özel tadımlar ve villadaki akşamlara davetler. Nadiren, elle yazılarak gönderilir.\",\n    \"foot.subscribe\": \"Abone ol\",\n    \"foot.thanks\": \"Teşekkürler — karşılama mektubunuz yolda.\",\n    \"foot.antalyaTime\": \"Antalya yerel saati\",\n    \"foot.currently\": \"Şu anda\",\n    \"foot.currentlyValue\": \"28° · Açık\",\n    \"foot.frontDesk\": \"Resepsiyon\",\n    \"foot.frontDeskValue\": \"24 saat açık\",\n    \"foot.discover\": \"Keşfet\",\n    \"foot.plan\": \"Planlama\",\n    \"foot.ourStory\": \"Hikâyemiz\",\n    \"foot.roomsSuites\": \"Odalar & Süitler\",\n    \"foot.dining\": \"Restoranlar\",\n    \"foot.experiences\": \"Deneyimler\",\n    \"foot.weddings\": \"Düğünler\",\n    \"foot.reservations\": \"Rezervasyonlar\",\n    \"foot.backToTop\": \"Başa dön\",\n    \"foot.rights\": \"Tüm hakları saklıdır.\",\n    \"music.play\": \"Müziği çal\",\n    \"music.pause\": \"Müziği duraklat\",\n    \"foot.mq.est\": \"Kuruluş MMXXVI\",\n    \"foot.mq.seaside\": \"Deniz Kıyısında Lüks\",\n    \"foot.mq.soul\": \"Akdeniz Ruhu\",\n    \"foot.mq.concierge\": \"Özel Konsiyerj\",\n    \"nav.toggleLang\": \"Dili değiştir\",\n    \"nav.language\": \"Dil\",\n    \"nav.season\": \"Sezon\",\n    \"nav.home\": \"Villa Aurelia — ana sayfa\",\n    \"rooms.prevImage\": \"Önceki görsel\",\n    \"rooms.nextImage\": \"Sonraki görsel\",\n    \"rooms.image\": \"Görsel\",\n    \"exp.stripLabel\": \"Deneyimler — yatay kaydırın\",\n    \"dine.venue\": \"Mekân\",\n    \"dine.videoLabel\": \"Şefimiz mutfakta\",\n    \"book.sending\": \"Gönderiliyor…\",\n    \"book.err.dates\": \"Lütfen giriş ve çıkış tarihlerini seçin.\",\n    \"book.err.full\": \"Seçtiğiniz aralıkta dolu geceler var.\",\n    \"book.err.room\": \"Lütfen bir oda tipi seçin.\",\n    \"book.err.name\": \"Lütfen adınızı ve soyadınızı yazın.\",\n    \"book.err.email\": \"Geçerli bir e-posta adresi girin.\",\n    \"book.err.phone\": \"Geçerli bir telefon numarası girin.\",\n    \"book.success\": \"Talebiniz bize ulaştı\",\n    \"book.successBody\": \"Misafir ilişkileri ekibimiz 24 saat içinde rezervasyonunuzu onaylayacak.\",\n    \"book.fail\": \"Talebiniz gönderilemedi. Lütfen tekrar deneyin.\",\n    \"foot.emailLabel\": \"E-posta adresiniz\",\n    \"notFound.title\": \"Bu sayfa henüz yazılmadı.\",\n    \"notFound.back\": \"Ana sayfaya dön\"\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/i18n/tr.ts\n");

